import { z } from 'zod';

export async function readPrivate<T>(
  url: string,
  getToken: () => Promise<string | null>,
  schema: z.ZodType<T>,
  signal: AbortSignal,
): Promise<T> {
  const token = await getToken();
  if (!token) throw new Error('Sign in to open your cloud garden.');
  const response = await fetch(url, {
    headers: { Authorization: `Bearer ${token}` },
    signal,
  });
  if (!response.ok) throw new Error(`Request failed: ${response.status}`);
  const value: unknown = await response.json();
  return schema.parse(value);
}

import { Text, Button, View } from 'react-native';
import { useRouter } from 'expo-router';
import { useSessionApi } from '../services/session';

export function CloudNotice() {
  const { kind } = useSessionApi();
  const router = useRouter();
  if (kind === 'guest') {
    return (
      <View style={{ gap: 12 }}>
        <Text>Your guest garden is stored locally.</Text>
        <Button title="Sign in for cloud features"
          onPress={() => router.push('/login')} />
      </View>
    );
  }
  return <Text>Your cloud requests use your signed-in session.</Text>;
}
